 {Host h;auto&p=h.p;assert(kOpenHatRule==533&&kRideRule==534&&kCrashRule==535);assert(p.proxyTarget(12)==kHatRhythmFull&&p.proxyTarget(13)==kOpenHatRule&&p.proxyTarget(14)==kRideRule&&p.proxyTarget(15)==kCrashRule);p.set(kEditor,1);for(int n=12;n<16;++n)assert(p.proxyTarget(n)==-1);}
