 for(int mode=3;mode<=5;++mode){Host h;h.p.set(kCrashRule,mode);h.playing=true;h.until(72);auto crash=hits(h,9);int interval=mode==3?4:mode==4?8:16;assert(crash.size()==size_t(17/interval+1));for(auto [b,t]:crash)assert(b%interval==0&&t==0);}
 {Host h;h.p.set(kCrashRule,1);h.playing=true;h.until(32);assert((hits(h,9)==std::vector<std::pair<int,int>>({{0,0}})));}
