 {Host h;auto&p=h.p;p.set(kRideRule,4);p.set(kOpenHatRule,2);p.set(kCrashRule,5);for(int i=0;i<100;++i)h.pulse(kRoll);assert(p.getInt(kRideRule)==4&&p.getInt(kOpenHatRule)==2&&p.getInt(kCrashRule)==5);auto state=p.internalSaveState();Host copy;assert(copy.p.internalLoadState(state.data(),state.size()));copy.p.reset();copy.block();assert(copy.p.internalSaveState()==state);p.set(kDensity,0);h.playing=true;h.until(8);assert(h.events.empty());}
 {Host h;auto&p=h.p;p.set(kRideRule,4);p.set(kCrashRule,3);h.playing=true;h.until(8);bool ride=false,crash=false,bell=false;for(auto&v:p.voices){ride|=v.active&&v.articulation==1;crash|=v.active&&v.articulation==2;bell|=v.active&&v.articulation==3;}assert(p.cymbalFallback[0].numFrames()!=p.cymbalFallback[1].numFrames());assert(p.cymbalFallback[0].channels[0]!=p.cymbalFallback[2].channels[0]);}
 {Host h;auto&p=h.p;p.set(kChoke0+6*9,1);p.triggerCymbal(0,80,500);int ride=-1;for(int i=0;i<int(p.voices.size());++i)if(p.voices[i].active&&p.voices[i].articulation==1)ride=i;assert(ride>=0);p.startLayerVoice(p.voices[ride]);p.triggerCymbal(1,94,500);for(auto&v:p.voices)if(v.active&&v.articulation==2)p.startLayerVoice(v);assert(p.voices[ride].choke<1);}
