 auto rideEnergy=[](float hat,float perc){Host h;auto&p=h.p;for(auto&c:p.notes[4])c.data.store(0);p.set(kRideRule,1);p.set(kMixHat,hat);p.set(kMixPerc,perc);h.playing=true;h.until(8);double energy=0;while(h.ppq<16){h.block();for(int c=0;c<2;++c)for(float v:h.data[c])energy+=v*v;}return energy;};double loud=rideEnergy(0,-48),quiet=rideEnergy(-48,0);assert(loud>.001&&quiet<loud*.001);std::cout<<"PASS Ride follows MAIN Hat Mix, independently of Perc Mix\n";
